<?php require 'config.php';require_role('organisasi');$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM events WHERE kegiatan_id=? AND organisasi_id=?');$s->execute([$id,user()['user_id']]);$ev=$s->fetch();if(!$ev)exit('Kegiatan tidak ditemukan');check_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['decision'])){$rid=(int)$_POST['rid'];$decision=$_POST['decision'];$s=db()->prepare("SELECT r.* FROM registrations r WHERE r.pendaftaran_id=? AND r.kegiatan_id=? AND r.status='Menunggu Verifikasi'");$s->execute([$rid,$id]);$r=$s->fetch();if($r&&in_array($decision,['Diterima','Ditolak'],true)){
if($decision==='Diterima'){$s=db()->prepare("SELECT COUNT(*) FROM registrations WHERE kegiatan_id=? AND status='Diterima'");$s->execute([$id]);if((int)$s->fetchColumn()>=$ev['kuota']){flash('error','Kuota telah terpenuhi.');redirect("manage_event.php?id=$id");}}
db()->prepare('UPDATE registrations SET status=? WHERE pendaftaran_id=?')->execute([$decision,$rid]);flash('success','Status pendaftar diperbarui.');}redirect("manage_event.php?id=$id");}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['finish'])){db()->prepare("UPDATE events SET status='Selesai' WHERE kegiatan_id=?")->execute([$id]);flash('success','Kegiatan ditandai selesai.');redirect("manage_event.php?id=$id");}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['issue'])){db()->beginTransaction();try{$s=db()->prepare("SELECT r.pendaftaran_id,r.volunteer_id FROM registrations r JOIN attendances a ON a.pendaftaran_id=r.pendaftaran_id WHERE r.kegiatan_id=? AND r.status='Diterima' AND a.status_kehadiran='Hadir' AND NOT EXISTS(SELECT 1 FROM certificates c WHERE c.pendaftaran_id=r.pendaftaran_id)");$s->execute([$id]);foreach($s->fetchAll() as $r){$num='VH-'.date('Y').'-'.strtoupper(bin2hex(random_bytes(4)));db()->prepare('INSERT INTO certificates(pendaftaran_id,nomor_sertifikat,tanggal_terbit) VALUES(?,?,CURDATE())')->execute([$r['pendaftaran_id'],$num]);}
db()->prepare("UPDATE contribution_history h SET jumlah_kegiatan=(SELECT COUNT(*) FROM certificates c JOIN registrations r ON r.pendaftaran_id=c.pendaftaran_id WHERE r.volunteer_id=h.volunteer_id),total_jam=(SELECT COALESCE(SUM(e.durasi_jam),0) FROM certificates c JOIN registrations r ON r.pendaftaran_id=c.pendaftaran_id JOIN events e ON e.kegiatan_id=r.kegiatan_id WHERE r.volunteer_id=h.volunteer_id),jumlah_sertifikat=(SELECT COUNT(*) FROM certificates c JOIN registrations r ON r.pendaftaran_id=c.pendaftaran_id WHERE r.volunteer_id=h.volunteer_id) WHERE h.volunteer_id IN (SELECT r.volunteer_id FROM registrations r WHERE r.kegiatan_id=?)")->execute([$id]);db()->commit();flash('success','Sertifikat diterbitkan untuk peserta yang hadir.');}catch(Throwable $e){db()->rollBack();flash('error','Gagal menerbitkan sertifikat.');}redirect("manage_event.php?id=$id");}
$s=db()->prepare("SELECT r.*,u.nama,u.email,v.skill FROM registrations r JOIN users u ON u.user_id=r.volunteer_id LEFT JOIN volunteers v ON v.user_id=r.volunteer_id WHERE r.kegiatan_id=? ORDER BY r.tanggal_daftar");$s->execute([$id]);$rows=$s->fetchAll();
layout_start('Kelola Pendaftar');?><a class="back" href="dashboard.php">← Dashboard</a><div class="page-heading"><span class="eyebrow">MANAJEMEN KEGIATAN</span><h1><?=e($ev['nama_kegiatan'])?></h1><p>Status: <?=badge($ev['status'])?></p></div><div class="section-head"><h2>Daftar pendaftar</h2><span class="count"><?=count($rows)?> orang</span></div><div class="table-wrap"><table><tr><th>Volunteer</th><th>Skill</th><th>Status</th><th>Keputusan</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['nama'])?></b><br><small><?=e($r['email'])?></small></td><td><?=e($r['skill'])?></td><td><?=badge($r['status'])?></td><td><?php if($r['status']==='Menunggu Verifikasi'):?><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="rid" value="<?=$r['pendaftaran_id']?>"><button name="decision" value="Diterima" class="btn btn-primary small">Terima</button><button name="decision" value="Ditolak" class="btn btn-outline small">Tolak</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></table></div><div class="action-panel"><div><h3>Absensi & sertifikat</h3><p class="muted">Volunteer dapat memindai QR atau memasukkan kode berikut pada halaman Check-in:</p><b id="checkincode"><?=e($ev['kegiatan_id'])?>-<?=substr(hash('sha256',(string)$ev['kegiatan_id']),0,8)?></b><div id="qrcode" style="margin-top:12px"></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>new QRCode(document.getElementById("qrcode"),{text:document.getElementById("checkincode").innerText,width:132,height:132});</script></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button class="btn btn-outline" name="finish" value="1">Tandai selesai</button><button class="btn btn-primary" name="issue" value="1">Terbitkan sertifikat hadir</button></form></div><?php layout_end(); ?>